      {/* 1. Page Header */}
      <div className="px-6 pt-4 pb-3 shrink-0 flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-slate-200/80 dark:border-slate-800 bg-white dark:bg-[#161f30] shadow-xs">
        <div>
