                  {/* Fixed Column 5: Son Çalıştırma */}
                  <th className="py-3.5 px-3 w-[140px] min-w-[140px] max-w-[140px] whitespace-nowrap">SON ÇALIŞTIRMA</th>

                  {/* Fixed Column 6: İşlemler */}
