                    stroke="#8b5cf6"
                    strokeWidth="12"
                    strokeDasharray={`${blockedStroke} ${circ}`}
                    strokeDashoffset={blockedOffset}
                    fill="transparent"
                    className="transition-all duration-500"
                  />
                </svg>
                {/* Center text */}
                <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
                  <span className="text-lg sm:text-xl font-bold font-mono text-slate-900 dark:text-slate-100">
                    {distributionStats.total}
                  </span>
                  <span className="text-[9px] text-slate-400 font-semibold uppercase tracking-wider">
                    {distributionRange === '1D' ? '24 Saat' : distributionRange === '7D' ? '7 Gün' : distributionRange === '30D' ? '30 Gün' : 'Toplam'}
                  </span>
                </div>
              </div>

              {/* Legend with counts and percentages */}
              <div className="space-y-2 text-xs flex-1">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 shrink-0"></span>
                    <span className="text-slate-700 dark:text-slate-200 font-medium">Başarılı</span>
                  </div>
                  <span className="font-mono text-slate-700 dark:text-slate-300 font-bold">
                    {distributionStats.passed} (%{distributionStats.passPercent})
                  </span>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-rose-500 shrink-0"></span>
                    <span className="text-slate-700 dark:text-slate-200 font-medium">Başarısız</span>
                  </div>
                  <span className="font-mono text-rose-600 dark:text-rose-400 font-bold">
                    {distributionStats.failed} (%{distributionStats.failPercent})
                  </span>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-amber-500 shrink-0"></span>
                    <span className="text-slate-700 dark:text-slate-200 font-medium">Atlandı</span>
                  </div>
                  <span className="font-mono text-slate-700 dark:text-slate-300 font-bold">
                    {distributionStats.skipped} (%{distributionStats.skippedPercent})
                  </span>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-purple-500 shrink-0"></span>
                    <span className="text-slate-700 dark:text-slate-200 font-medium">Bloke</span>
                  </div>
                  <span className="font-mono text-slate-700 dark:text-slate-300 font-bold">
                    {distributionStats.blocked} (%{distributionStats.blockedPercent})
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Widget 3: En Çok Hata Alan Senaryolar (Most Failing Cases) */}
          <div className="p-4 sm:p-5 rounded-2xl bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-[#2e3748] shadow-xs space-y-3">
            <div className="flex items-center justify-between border-b border-slate-100 dark:border-[#2e3748]/60 pb-2.5">
              <h3 className="text-base font-bold text-slate-900 dark:text-slate-100 flex items-center gap-2">
                <Bug className="w-4 h-4 text-rose-500" />
                <span>En Çok Hata Alan Senaryolar</span>
              </h3>
              {onNavigateToExplorer && (
                <button
                  onClick={onNavigateToExplorer}
                  className="text-xs font-semibold text-blue-600 dark:text-blue-400 hover:underline"
                >
                  Tümünü Gör
                </button>
              )}
            </div>

            <div className="space-y-3">
              {displayedFailingCases.length === 0 ? (
                <div className="p-3 text-center text-xs text-slate-400">
                  <CheckCircle2 className="w-6 h-6 mx-auto mb-1 text-emerald-500 opacity-70" />
                  <p>Harika! Şu anda hata alan senaryo bulunmuyor.</p>
                </div>
              ) : (
                displayedFailingCases.map(({ tc, failCount }) => {
                  const widthPercent = Math.max(Math.round((failCount / maxFailCount) * 100), 20);
                  return (
                    <div
                      key={tc.id}
                      onClick={() => onSelectCase && onSelectCase(tc)}
                      className="space-y-1 cursor-pointer group"
                    >
                      <div className="flex items-center justify-between text-xs">
                        <div className="flex items-center space-x-2 truncate max-w-[200px]">
                          <span className="font-mono font-bold text-rose-600 dark:text-rose-400">
                            {tc.code}
                          </span>
                          <span className="text-slate-800 dark:text-slate-200 font-medium group-hover:text-rose-500 transition-colors truncate">
                            {tc.title}
                          </span>
                        </div>
                        <span className="font-mono text-xs font-bold px-1.5 py-0.2 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 shrink-0">
                          {failCount} Hata
                        </span>
                      </div>
                      <div className="w-full bg-slate-200/80 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
                        <div
                          className="bg-gradient-to-r from-rose-500 to-rose-600 h-full rounded-full transition-all duration-300"
                          style={{ width: `${widthPercent}%` }}
                        />
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      </div>

      {/* 4. Bottom Section: Hızlı İşlemler (Quick Actions Bar) */}
      <div className="p-4 sm:p-5 rounded-2xl bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-[#2e3748] shadow-xs space-y-3">
        <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-[#8e9bb0]">
          Hızlı İşlemler
        </h3>
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
          {/* Action 1: Yeni Test Senaryosu */}
          <button
            onClick={onOpenNewCase}
            className="flex items-center justify-center gap-2 p-3 rounded-xl bg-slate-50 dark:bg-[#262e3d]/60 hover:bg-blue-500/10 hover:border-blue-500/30 border border-slate-200 dark:border-[#2e3748] text-slate-800 dark:text-slate-200 hover:text-blue-600 dark:hover:text-blue-400 transition-all font-semibold text-xs sm:text-sm cursor-pointer shadow-xs active:scale-98"
          >
            <FilePlus className="w-4 h-4 text-blue-500" />
            <span className="truncate">Yeni Test Senaryosu</span>
          </button>

          {/* Action 2: Test Planı Oluştur */}
          <button
            onClick={onOpenNewPlan || onNavigateToPlans}
            className="flex items-center justify-center gap-2 p-3 rounded-xl bg-slate-50 dark:bg-[#262e3d]/60 hover:bg-emerald-500/10 hover:border-emerald-500/30 border border-slate-200 dark:border-[#2e3748] text-slate-800 dark:text-slate-200 hover:text-emerald-600 dark:hover:text-emerald-400 transition-all font-semibold text-xs sm:text-sm cursor-pointer shadow-xs active:scale-98"
          >
            <Calendar className="w-4 h-4 text-emerald-500" />
            <span className="truncate">Test Planı Oluştur</span>
          </button>

          {/* Action 3: Test Çalıştırması Başlat */}
          <button
            onClick={onOpenManualRun}
            className="flex items-center justify-center gap-2 p-3 rounded-xl bg-emerald-50/50 dark:bg-emerald-950/20 hover:bg-emerald-500/15 hover:border-emerald-500/40 border border-emerald-500/20 text-emerald-700 dark:text-emerald-300 hover:text-emerald-800 dark:hover:text-emerald-200 transition-all font-bold text-xs sm:text-sm cursor-pointer shadow-xs active:scale-98"
          >
            <Play className="w-4 h-4 text-emerald-600 dark:text-emerald-400 fill-current" />
            <span className="truncate">Koşum Başlat</span>
          </button>

          {/* Action 4: Defect Oluştur */}
          <button
            onClick={onNavigateToReports}
            className="flex items-center justify-center gap-2 p-3 rounded-xl bg-slate-50 dark:bg-[#262e3d]/60 hover:bg-rose-500/10 hover:border-rose-500/30 border border-slate-200 dark:border-[#2e3748] text-slate-800 dark:text-slate-200 hover:text-rose-600 dark:hover:text-rose-400 transition-all font-semibold text-xs sm:text-sm cursor-pointer shadow-xs active:scale-98"
          >
            <Bug className="w-4 h-4 text-rose-500" />
            <span className="truncate">Defect Bildir</span>
          </button>

          {/* Action 5: Raporlar */}
          <button
            onClick={onNavigateToReports}
            className="flex items-center justify-center gap-2 p-3 rounded-xl bg-slate-50 dark:bg-[#262e3d]/60 hover:bg-amber-500/10 hover:border-amber-500/30 border border-slate-200 dark:border-[#2e3748] text-slate-800 dark:text-slate-200 hover:text-amber-600 dark:hover:text-amber-400 transition-all font-semibold text-xs sm:text-sm cursor-pointer shadow-xs active:scale-98"
          >
            <BarChart3 className="w-4 h-4 text-amber-500" />
            <span className="truncate">Raporlar & Analiz</span>
          </button>

          {/* Action 6: Test Suite Ekle */}
          <button
            onClick={onOpenNewSuite}
            className="flex items-center justify-center gap-2 p-3 rounded-xl bg-slate-50 dark:bg-[#262e3d]/60 hover:bg-teal-500/10 hover:border-teal-500/30 border border-slate-200 dark:border-[#2e3748] text-slate-800 dark:text-slate-200 hover:text-teal-600 dark:hover:text-teal-400 transition-all font-semibold text-xs sm:text-sm cursor-pointer shadow-xs active:scale-98"
          >
            <FolderPlus className="w-4 h-4 text-teal-500" />
            <span className="truncate">Yeni Test Suite</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export const SuiteCasesView: React.FC<SuiteCasesViewProps> = ({
  suite,
  allSuites = [],
  onSelectCase,
  onSelectSuite,
  onAddSubSuite,
  onAddCaseInSuite,
  onRunCase,
  onClose,
  onBack,
}) => {
  const { can, isViewer } = useAuth();
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ALL');

  const [priorityFilter, setPriorityFilter] = useState<string>('ALL');
  const [typeFilter, setTypeFilter] = useState<string>('ALL');

  // Suite default version and environment
  const [defaultVersion, setDefaultVersion] = useState('v1.0.0');
  const [defaultEnvironment, setDefaultEnvironment] = useState('STAGING');

  // Per-testcase custom version and environment overrides
  const [caseVersions, setCaseVersions] = useState<Record<string, string>>({});
  const [caseEnvironments, setCaseEnvironments] = useState<Record<string, string>>({});

  if (!suite) return null;

  const testCases = suite.testCases || [];
  const childSuites = suite.children || [];

  // Calculate suite stats
  const stats = {
    total: testCases.length,
    passed: testCases.filter((c) => c.results && c.results.length > 0 && c.results[0].status === 'PASSED').length,
    failed: testCases.filter((c) => c.results && c.results.length > 0 && c.results[0].status === 'FAILED').length,
    blocked: testCases.filter((c) => c.results && c.results.length > 0 && c.results[0].status === 'BLOCKED').length,
    untested: testCases.filter((c) => !c.results || c.results.length === 0).length,
  };

  const passRate = stats.total > 0 ? Math.round((stats.passed / stats.total) * 100) : 0;

  // Filter test cases
  const filteredCases = testCases.filter((tc) => {
    const matchesSearch = searchQuery
      ? tc.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        tc.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (tc.description && tc.description.toLowerCase().includes(searchQuery.toLowerCase()))
      : true;

    const latestStatus = tc.results && tc.results.length > 0 ? tc.results[0].status : 'UNTESTED';
    const matchesStatus =
      statusFilter === 'ALL'
        ? true
        : statusFilter === 'UNTESTED'
        ? !tc.results || tc.results.length === 0
        : latestStatus === statusFilter;

    const matchesPriority = priorityFilter === 'ALL' ? true : tc.priority === priorityFilter;
    const matchesType = typeFilter === 'ALL' ? true : tc.type === typeFilter;

    return matchesSearch && matchesStatus && matchesPriority && matchesType;
  });

  const getPriorityBadge = (priority: Priority) => {
    switch (priority) {
      case 'BLOCKER':
        return 'bg-rose-100 dark:bg-rose-950/80 text-rose-700 dark:text-rose-300 border-rose-300 dark:border-rose-700/60 shadow-xs';
      case 'CRITICAL':
        return 'bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border-amber-300 dark:border-amber-700/60 shadow-xs';
      case 'NORMAL':
        return 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 border-slate-300 dark:border-slate-600 shadow-xs';
      case 'LOW':
        return 'bg-slate-50 dark:bg-slate-900 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-800 shadow-xs';
      default:
        return 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border-slate-300 dark:border-slate-700 shadow-xs';
    }
  };

  const getTypeBadge = (type: TestType) => {
    return 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700';
  };

  const renderStatusPill = (tc: TestCase) => {
    const latestResult = tc.results && tc.results.length > 0 ? tc.results[0] : null;
    if (!latestResult) {
      return (
        <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700 font-mono font-medium">
          UNTESTED
        </span>
      );
    }

    switch (latestResult.status) {
      case 'PASSED':
        return (
          <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 font-mono font-bold">
            <CheckCircle2 className="w-3 h-3 text-emerald-500 shrink-0" />
            <span>PASSED</span>
          </span>
        );
      case 'FAILED':
        return (
          <span
            className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-rose-500/15 text-rose-600 dark:text-rose-400 border border-rose-500/30 font-mono font-bold"
            title={latestResult.errorMessage || 'Test Başarısız Oldu'}
          >
            <XCircle className="w-3 h-3 text-rose-500 shrink-0" />
            <span>FAILED</span>
          </span>
        );
      case 'SKIPPED':
        return (
          <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-slate-500/15 text-slate-600 dark:text-slate-400 border border-slate-500/30 font-mono font-bold">
            <SkipForward className="w-3 h-3 text-slate-400 shrink-0" />
            <span>SKIPPED</span>
          </span>
        );
      case 'BLOCKED':
        return (
          <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/30 font-mono font-bold">
            <Slash className="w-3 h-3 text-amber-500 shrink-0" />
            <span>BLOCKED</span>
          </span>
        );
      default:
        return null;
    }
  };

  const handleApplyDefaultSettingsToAll = () => {
    const newVersions: Record<string, string> = {};
    const newEnvironments: Record<string, string> = {};
    testCases.forEach((tc) => {
      newVersions[tc.id] = defaultVersion;
      newEnvironments[tc.id] = defaultEnvironment;
    });
    setCaseVersions(newVersions);
    setCaseEnvironments(newEnvironments);
  };

  const getCaseVersion = (caseId: string) => {
    return caseVersions[caseId] || defaultVersion;
  };

  const getCaseEnvironment = (caseId: string) => {
    return caseEnvironments[caseId] || defaultEnvironment;
  };

  const handleRunTestCaseRow = (tc: TestCase) => {
    const version = getCaseVersion(tc.id);
    const environment = getCaseEnvironment(tc.id);
    if (onRunCase) {
      onRunCase(tc, version, environment);
    }
  };

  return (
    <main className="flex-1 overflow-y-auto overflow-x-hidden bg-slate-50 dark:bg-[#090d16] text-slate-800 dark:text-slate-100 p-4 sm:p-6 space-y-6 transition-colors duration-200 min-w-0">
      {/* Suite Header Section */}
      <div className="bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm space-y-4">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="flex items-center space-x-3 min-w-0">
            {onBack && (
              <button
                type="button"
                onClick={onBack}
                className="flex items-center space-x-1.5 px-3 py-2 text-xs font-semibold rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 shadow-sm transition-all active:scale-95 cursor-pointer shrink-0"
                title="Önceki ekrana dön"
              >
                <ArrowLeft className="w-3.5 h-3.5 text-rose-500" />
                <span>Geri</span>
              </button>
            )}
            <div className={`w-11 h-11 rounded-xl flex items-center justify-center border shrink-0 ${
              suite.id === '__root_cases__'
                ? 'bg-[#b83a4b]/10 text-[#b83a4b] dark:text-[#d66b7a] border-[#b83a4b]/20'
                : 'bg-amber-500/10 text-amber-500 border-amber-500/20'
            }`}>
              {suite.id === '__root_cases__' ? <FileText className="w-6 h-6" /> : <FolderOpen className="w-6 h-6" />}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex items-center flex-wrap gap-2">
                <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100 truncate">{suite.name}</h2>
                <span className="text-xs px-2.5 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700 font-mono font-bold shrink-0">
                  {stats.total} Test Case
                </span>
                {childSuites.length > 0 && (
                  <span className="text-xs px-2.5 py-0.5 rounded-full bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20 font-mono font-bold shrink-0">
                    {childSuites.length} Alt Klasör
                  </span>
                )}
              </div>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5 truncate">
                {suite.id === '__root_cases__'
                  ? "Herhangi bir test suite'e bağlı olmayan kök test case listesi ve koşu yönetimi"
                  : "Suite içindeki test case listesi, versiyon/ortam seçimi ve koşu yönetimi"}
              </p>
            </div>
          </div>

          <div className="flex items-center flex-wrap gap-2 shrink-0">
            <button
              type="button"
              onClick={() => {
                // Client-side quick suite CSV export
                const BOM = '\uFEFF';
                const headers = ['Test Kodu', 'Başlık', 'Öncelik', 'Tip', 'Yürütme Türü', 'Son Durum', 'Jira Story', 'Jira Bug'];
                const rows = (suite.testCases || []).map((tc) => [
                  `"${tc.code}"`,
                  `"${(tc.title || '').replace(/"/g, '""')}"`,
                  `"${tc.priority}"`,
                  `"${tc.type}"`,
                  `"${tc.executionType || 'MANUAL'}"`,
                  `"${tc.results && tc.results.length > 0 ? tc.results[0].status : 'UNTESTED'}"`,
                  `"${tc.jiraStoryKey || ''}"`,
                  `"${tc.results && tc.results.length > 0 ? tc.results[0].jiraBugKey || '' : ''}"`,
                ]);
                const csvContent = BOM + [headers.map((h) => `"${h}"`).join(','), ...rows.map((r) => r.join(','))].join('\r\n');
                const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `${suite.id === '__root_cases__' ? 'Kok_Test_Caseleri' : `Suite_${suite.name.replace(/[^a-zA-Z0-9_-]/g, '_')}`}_Report.csv`;
                a.click();
                URL.revokeObjectURL(url);
              }}
              className="flex items-center space-x-1.5 px-3 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-semibold rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm transition-all active:scale-95 cursor-pointer"
              title="Test Senaryolarını CSV Formatında İndir"
            >
              <FileCode2 className="w-4 h-4 text-emerald-500" />
              <span>Rapor (CSV)</span>
            </button>

            {suite.id !== '__root_cases__' && onAddSubSuite && can('CREATE_SUITE') && (
              <button
                type="button"
                onClick={() => onAddSubSuite(suite.id)}
                className="flex items-center space-x-1.5 px-3.5 py-2 bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 text-xs font-semibold rounded-xl shadow-sm transition-all active:scale-95 cursor-pointer"
              >
                <FolderPlus className="w-4 h-4 text-amber-500" />
                <span>+ Alt Klasör Ekle</span>
              </button>
            )}

            {can('CREATE_CASE') && (
              <button
                type="button"
                onClick={() => onAddCaseInSuite(suite.id === '__root_cases__' ? '' : suite.id)}
                className="flex items-center space-x-1.5 px-3.5 py-2 bg-[#b83a4b] hover:bg-[#a32e3e] text-white text-xs font-semibold rounded-xl shadow-md shadow-[#b83a4b]/20 transition-all active:scale-95 cursor-pointer"
              >
                <Plus className="w-4 h-4" />
                <span>Yeni Case</span>
              </button>
            )}

            {onClose && (
              <button
                type="button"
                onClick={onClose}
                className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors cursor-pointer"
                title="Kapat"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>
        </div>

        {/* Stats Summary Bar */}
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 pt-3 border-t border-slate-100 dark:border-slate-800/80">
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Başarı Oranı</span>
            <div className="text-base font-bold text-emerald-500">{passRate}%</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Passed</span>
            <div className="text-base font-bold text-emerald-600 dark:text-emerald-400">{stats.passed}</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Failed</span>
            <div className="text-base font-bold text-rose-600 dark:text-rose-400">{stats.failed}</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Blocked</span>
            <div className="text-base font-bold text-amber-600 dark:text-amber-400">{stats.blocked}</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Koşulmadı</span>
            <div className="text-base font-bold text-slate-500">{stats.untested}</div>
          </div>
        </div>
      </div>

      {/* Sub-Suites / Alt Klasörler Section */}
      {childSuites.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200 flex items-center space-x-2">
              <Folder className="w-4 h-4 text-amber-500" />
              <span>Alt Klasörler (Sub-Suites) ({childSuites.length})</span>
            </h3>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {childSuites.map((child) => {
              const childCasesCount = child.testCases ? child.testCases.length : 0;
              const childSubSuitesCount = child.children ? child.children.length : 0;
              return (
                <div
                  key={child.id}
                  onClick={() => onSelectSuite && onSelectSuite(child)}
                  className="group p-3.5 rounded-2xl bg-white dark:bg-slate-900/80 hover:bg-amber-500/5 dark:hover:bg-amber-500/10 border border-slate-200 dark:border-slate-800 hover:border-amber-500/50 transition-all shadow-sm hover:shadow cursor-pointer flex items-center justify-between"
                >
                  <div className="flex items-center space-x-3 min-w-0">
                    <div className="w-9 h-9 rounded-xl bg-amber-500/10 text-amber-500 flex items-center justify-center border border-amber-500/20 group-hover:scale-105 transition-transform shrink-0">
                      <FolderOpen className="w-5 h-5" />
                    </div>
                    <div className="min-w-0">
                      <h4 className="text-xs font-bold text-slate-800 dark:text-slate-200 group-hover:text-amber-600 dark:group-hover:text-amber-400 transition-colors truncate">
                        {child.name}
                      </h4>
                      <div className="flex items-center space-x-2 text-[10px] text-slate-400 font-mono mt-0.5">
                        <span>{childCasesCount} Case</span>
                        {childSubSuitesCount > 0 && <span>&bull; {childSubSuitesCount} Alt Klasör</span>}
                      </div>
                    </div>
                  </div>

                  <ChevronRight className="w-4 h-4 text-slate-400 group-hover:text-amber-500 group-hover:translate-x-0.5 transition-all shrink-0 ml-2" />
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Toolbar & Filter & Batch Config Bar */}
      <div className="space-y-3">
        <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-3 bg-white dark:bg-slate-900/70 p-3.5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
          {/* Search Input */}
          <div className="relative flex-1 min-w-[200px] max-w-md">
            <Search className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              placeholder="Test Case başlığı, kod veya açıklama ara..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 pl-9 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-rose-500 transition-colors"
            />
          </div>

          {/* Filter Dropdowns */}
          <div className="flex items-center flex-wrap gap-2 text-xs">
            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as StatusFilter)}
              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl px-3 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
            >
              <option value="ALL">Tüm Durumlar</option>
              <option value="PASSED">Passed</option>
              <option value="FAILED">Failed</option>
              <option value="BLOCKED">Blocked</option>
              <option value="UNTESTED">Untested</option>
            </select>

            {/* Priority Filter */}
            <select
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value)}
              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl px-3 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
            >
              <option value="ALL">Tüm Öncelikler</option>
              <option value="BLOCKER">🔴 BLOCKER</option>
              <option value="CRITICAL">🟠 CRITICAL</option>
              <option value="NORMAL">🔵 NORMAL</option>
              <option value="LOW">⚪ LOW</option>
            </select>

            {/* Type Filter */}
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl px-3 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
            >
              <option value="ALL">Tüm Tipler</option>
              <option value="WEB">🌐 WEB</option>
              <option value="MOBILE">📱 MOBILE</option>
              <option value="API">⚡ API</option>
              <option value="MANUAL">📋 MANUAL</option>
            </select>
          </div>
        </div>

        {/* Global/Default Suite Run Settings Banner */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3 bg-rose-500/5 dark:bg-rose-500/10 border border-rose-500/20 rounded-2xl text-xs">
          <div className="flex items-center space-x-2">
            <Settings2 className="w-4 h-4 text-rose-500 shrink-0" />
            <span className="font-semibold text-slate-800 dark:text-slate-200">Varsayılan Koşu Parametreleri:</span>
            <span className="text-[11px] text-slate-500 dark:text-slate-400 hidden md:inline">
              (Liste satırları için genel versiyon ve ortam şablonu)
            </span>
          </div>

          <div className="flex items-center flex-wrap gap-2">
            <div className="flex items-center space-x-1.5 bg-white dark:bg-slate-900 px-2 py-1 rounded-xl border border-slate-200 dark:border-slate-800">
              <span className="text-[11px] text-slate-500 font-medium">Versiyon:</span>
              <input
                type="text"
                value={defaultVersion}
                onChange={(e) => setDefaultVersion(e.target.value)}
                placeholder="v1.0.0"
                className="w-20 bg-transparent text-xs font-mono font-bold text-slate-800 dark:text-slate-200 focus:outline-none"
              />
            </div>

            <div className="flex items-center space-x-1.5 bg-white dark:bg-slate-900 px-2 py-1 rounded-xl border border-slate-200 dark:border-slate-800">
              <span className="text-[11px] text-slate-500 font-medium">Ortam:</span>
              <select
                value={defaultEnvironment}
                onChange={(e) => setDefaultEnvironment(e.target.value)}
                className="bg-transparent text-xs font-bold text-slate-800 dark:text-slate-200 focus:outline-none cursor-pointer"
              >
                {PRESET_ENVIRONMENTS.map((env) => (
                  <option key={env} value={env}>
                    {env}
                  </option>
                ))}
              </select>
            </div>

            <button
              type="button"
              onClick={handleApplyDefaultSettingsToAll}
              className="flex items-center space-x-1 px-3 py-1 bg-rose-500 hover:bg-rose-600 text-white rounded-xl text-xs font-semibold shadow-sm transition-all active:scale-95 cursor-pointer"
              title="Bu versiyon ve ortamı aşağıdaki tüm test case satırlarına uygula"
            >
              <Check className="w-3.5 h-3.5" />
              <span>Tümüne Uygula</span>
            </button>
          </div>
        </div>
      </div>

      {/* Test Cases List / Table View */}
      {filteredCases.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl bg-white dark:bg-slate-900/40 text-slate-400 dark:text-slate-500">
          <Layers className="w-10 h-10 mb-3 opacity-30 text-slate-400" />
          <h4 className="text-sm font-semibold text-slate-700 dark:text-slate-300">
            {childSuites.length > 0 ? 'Bu Düzeyde Test Case Bulunmuyor' : 'Test Case Bulunamadı'}
          </h4>
          <p className="text-xs text-slate-500 mt-1 max-w-sm">
            {childSuites.length > 0
              ? 'Bu klasör içerisinde doğrudan tanımlı Test Case yok. Yukarıdaki alt klasörlere girebilir veya yeni case ekleyebilirsiniz.'
              : 'Bu suite içerisinde arama kriterlerinize uygun Test Case bulunmuyor veya henüz Test Case eklenmemiş.'}
          </p>
          <div className="flex items-center space-x-2 mt-4">
            {onAddSubSuite && (
              <button
                type="button"
                onClick={() => onAddSubSuite(suite.id)}
                className="px-3.5 py-1.5 bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 text-xs font-semibold rounded-lg shadow-sm transition-all"
              >
                + Alt Klasör Ekle
              </button>
            )}
            <button
              type="button"
              onClick={() => onAddCaseInSuite(suite.id)}
              className="px-3.5 py-1.5 bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold rounded-lg shadow-sm transition-all"
            >
              + Yeni Test Case Oluştur
            </button>
          </div>
        </div>
      ) : (
        <div className="w-full bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm overflow-hidden">
          <div className="overflow-x-auto w-full">
            <table className="w-full text-left text-xs border-collapse min-w-[920px]">
              <thead className="sticky top-0 z-10 bg-slate-100/90 dark:bg-[#1a2333] border-b border-slate-200 dark:border-slate-700/80 shadow-xs">
                <tr className="text-slate-700 dark:text-slate-200 font-bold uppercase tracking-wider text-[11px]">
                  <th className="py-2.5 px-3 text-center w-10">#</th>
                  <th className="py-2.5 px-3 w-28">Test Kodu</th>
                  <th className="py-2.5 px-4 min-w-[240px]">Test Case Başlığı ve Detay</th>
                  <th className="py-2.5 px-3 w-24 text-center">Öncelik</th>
                  <th className="py-2.5 px-3 w-24 text-center">Tip</th>
                  <th className="py-2.5 px-3 w-28 text-center">Son Durum</th>
                  <th className="py-2.5 px-3 w-64 text-center">Koşu Parametreleri</th>
                  <th className="py-2.5 px-4 w-44 text-right">İşlemler</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/80 text-slate-700 dark:text-slate-200">
                {filteredCases.map((tc, index) => {
                  const currentVersion = getCaseVersion(tc.id);
                  const currentEnv = getCaseEnvironment(tc.id);

                  return (
                    <tr
                      key={tc.id}
                      className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors group"
                    >
                      {/* Index */}
                      <td className="py-3 px-3 text-center font-mono text-[11px] text-slate-400">
                        {index + 1}
                      </td>

                      {/* Test Code */}
                      <td className="py-3 px-3">
                        <span className="font-mono text-[11px] font-bold px-2 py-0.5 rounded-lg bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 inline-flex items-center space-x-1 shrink-0">
                          <FileCode2 className="w-3 h-3" />
                          <span>{tc.code}</span>
                        </span>
                      </td>

                      {/* Title & Details */}
                      <td className="py-3 px-4">
                        <div className="space-y-1">
                          <div
                            onClick={() => onSelectCase(tc)}
                            className="font-bold text-slate-900 dark:text-slate-100 hover:text-rose-600 dark:hover:text-rose-400 cursor-pointer transition-colors text-xs leading-snug line-clamp-2"
                            title="Detayları İncelemek İçin Tıklayın"
                          >
                            {tc.title}
                          </div>

                          {tc.description && (
                            <p className="text-[11px] text-slate-500 dark:text-slate-400 line-clamp-1">
                              {tc.description}
                            </p>
                          )}

                          <div className="flex items-center space-x-2 pt-0.5 text-[10px] text-slate-400">
                            {/* Step Count */}
                            <span className="flex items-center space-x-1" title={`${tc.steps?.length || 0} Test Adımı`}>
                              <ListOrdered className="w-3 h-3" />
                              <span>{tc.steps?.length || 0} Adım</span>
                            </span>

                            {/* Screenshot Indicator */}
                            {tc.screenshotUrl && (
                              <span className="flex items-center space-x-0.5 text-emerald-500 font-semibold" title="Görsel Ekli">
                                <ImageIcon className="w-3 h-3" />
                                <span>Görsel</span>
                              </span>
                            )}

                            {/* Jira Story Indicator */}
                            {tc.jiraStoryKey && (
                              <span className="flex items-center space-x-0.5 text-blue-500 font-mono font-semibold" title={`Jira: ${tc.jiraStoryKey}`}>
                                <Sparkles className="w-2.5 h-2.5" />
                                <span>{tc.jiraStoryKey}</span>
                              </span>
                            )}
                          </div>
                        </div>
                      </td>

                      {/* Priority */}
                      <td className="py-3 px-3 text-center">
                        <span
                          className={`text-[9px] px-2 py-0.5 rounded-full border font-mono font-bold inline-block ${getPriorityBadge(
                            tc.priority
                          )}`}
                        >
                          {tc.priority}
                        </span>
                      </td>

                      {/* Type */}
                      <td className="py-3 px-3 text-center">
                        <span
                          className={`text-[9px] px-2 py-0.5 rounded-full border font-mono font-semibold inline-block ${getTypeBadge(
                            tc.type
                          )}`}
                        >
                          {tc.type}
                        </span>
                      </td>

                      {/* Latest Status */}
                      <td className="py-3 px-3 text-center">
                        {renderStatusPill(tc)}
                      </td>

                      {/* Run Parameters (Version & Environment) */}
                      <td className="py-3 px-3 text-center">
                        <div className="flex items-center justify-center space-x-1.5">
                          {/* Version Input/Select */}
                          <div className="relative">
                            <input
                              type="text"
                              value={currentVersion}
                              onChange={(e) =>
                                setCaseVersions((prev) => ({
                                  ...prev,
                                  [tc.id]: e.target.value,
                                }))
                              }
                              placeholder="v1.0.0"
                              title="Versiyon Numarası"
                              className="w-20 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700/80 rounded-lg px-2 py-1 text-[11px] font-mono font-medium text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-rose-500 text-center"
                            />
                          </div>

                          {/* Environment Select */}
                          <div className="relative">
                            <select
                              value={currentEnv}
                              onChange={(e) =>
                                setCaseEnvironments((prev) => ({
                                  ...prev,
                                  [tc.id]: e.target.value,
                                }))
                              }
                              title="Test Ortamı"
                              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700/80 rounded-lg px-2 py-1 text-[11px] font-semibold text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
                            >
                              {PRESET_ENVIRONMENTS.map((env) => (
                                <option key={env} value={env}>
                                  {env}
                                </option>
                              ))}
                            </select>
                          </div>
                        </div>
                      </td>

                      {/* Action Buttons ("İncele" & "Koştur") */}
                      <td className="py-3 px-4 text-right">
                        <div className="flex items-center justify-end space-x-1.5">
                          {/* "İncele" Butonu */}
                          <button
                            type="button"
                            onClick={() => onSelectCase(tc)}
                            className="inline-flex items-center space-x-1 px-2.5 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl text-xs font-semibold border border-slate-200 dark:border-slate-700 shadow-sm transition-all active:scale-95 cursor-pointer"
                            title="Test Case Detaylarını İncele ve Düzenle"
                          >
                            <Eye className="w-3.5 h-3.5 text-rose-500" />
                            <span>İncele</span>
                          </button>

                          {/* "Koştur" Butonu */}
                          {onRunCase && can('EXECUTE_RUN') && (
                            <button
                              type="button"
                              onClick={() => handleRunTestCaseRow(tc)}
                              className="inline-flex items-center space-x-1 px-3 py-1.5 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white rounded-xl text-xs font-bold shadow-md shadow-emerald-600/20 transition-all active:scale-95 cursor-pointer"
                              title={`${currentVersion} versiyonu ve ${currentEnv} ortamında test koşusunu başlat`}
                            >
                              <Play className="w-3.5 h-3.5 fill-current" />
                              <span>Koştur</span>
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </main>
  );
};

export type SidebarTab = 'DASHBOARD' | 'PLANS' | 'EXPLORER' | 'RUNS' | 'REPORTS';

interface AppSidebarProps {
  projects?: Project[];
  selectedProject?: Project | null;
  activeTab: SidebarTab;
  onTabChange: (tab: SidebarTab) => void;
  testCasesCount?: number;
  testPlansCount?: number;
  testRunsCount?: number;
  onOpenUserManagement?: () => void;
}

export const AppSidebar: React.FC<AppSidebarProps> = ({
  selectedProject,
  activeTab,
  onTabChange,
  testCasesCount = 0,
  testPlansCount = 0,
  testRunsCount = 0,
  onOpenUserManagement,
}) => {
  const { isAdmin } = useAuth();
  const [isCollapsed, setIsCollapsed] = useState<boolean>(false);

  // Load collapsed state from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('tcms_sidebar_collapsed');
    if (saved === 'true') {
      setIsCollapsed(true);
    }
  }, []);

  const toggleCollapsed = () => {
    setIsCollapsed((prev) => {
      const next = !prev;
      localStorage.setItem('tcms_sidebar_collapsed', String(next));
      return next;
    });
  };

  // Main Navigation Items Config
  const navItems = [
    {
      id: 'DASHBOARD' as SidebarTab,
      label: 'Ana Sayfa',
      icon: LayoutDashboard,
    },
    {
      id: 'PLANS' as SidebarTab,
      label: 'Test Planları',
      icon: ClipboardList,
      badge: testPlansCount > 0 ? testPlansCount : undefined,
    },
    {
      id: 'EXPLORER' as SidebarTab,
      label: 'Test Senaryoları',
      icon: FileText,
      badge: testCasesCount > 0 ? testCasesCount : undefined,
    },
    {
      id: 'RUNS' as SidebarTab,
      label: 'Test Koşumları',
      icon: Activity,
      badge: testRunsCount > 0 ? testRunsCount : undefined,
    },
    {
      id: 'REPORTS' as SidebarTab,
      label: 'Test Raporları',
      icon: BarChart3,
    },
  ];

  // Collapsed Sidebar View
  if (isCollapsed) {
    return (
      <aside className="w-16 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-[#0c121e] flex flex-col items-center py-3 h-[calc(100vh-4rem)] select-none transition-all duration-300 z-20 shrink-0 justify-between">
        <div className="flex flex-col items-center space-y-3 w-full">
          <button
            type="button"
            onClick={toggleCollapsed}
            className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800/80 hover:bg-[#b83a4b]/10 text-slate-600 dark:text-slate-300 hover:text-[#b83a4b] transition-colors shadow-xs mb-1 cursor-pointer"
            title="Menüyü Genişlet"
          >
            <PanelLeftOpen className="w-4.5 h-4.5" />
          </button>

          {/* Active Project Key Badge */}
          {selectedProject && (
            <div
              onClick={toggleCollapsed}
              className="w-10 h-10 rounded-xl bg-[#b83a4b]/15 text-[#b83a4b] dark:text-[#d66b7a] font-mono font-bold text-xs flex items-center justify-center border border-[#b83a4b]/30 mb-1 cursor-pointer shadow-xs"
              title={`Proje: ${selectedProject.name}`}
            >
              {selectedProject.name.charAt(0).toLocaleUpperCase('tr-TR')}
            </div>
          )}

          {/* Nav Icons */}
          <div className="flex flex-col space-y-2 w-full px-2">
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => onTabChange(item.id)}
                  className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all cursor-pointer relative group ${
                    isActive
                      ? 'bg-gradient-to-r from-[#b83a4b] to-[#821c2b] text-white shadow-md shadow-[#821c2b]/30 scale-105 font-bold'
                      : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800/80 hover:text-slate-900 dark:hover:text-slate-100'
                  }`}
                  title={item.label}
                >
                  <Icon className="w-4.5 h-4.5" />
                  {item.badge !== undefined && (
                    <span className="absolute top-1 right-1 w-2 h-2 rounded-full bg-[#b83a4b] ring-2 ring-white dark:ring-slate-900" />
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* Collapsed Footer: Admin Settings Icon & Expand Toggle */}
        <div className="flex flex-col items-center space-y-2 w-full px-2">
          {isAdmin && onOpenUserManagement && (
            <button
              type="button"
              onClick={onOpenUserManagement}
              className="w-10 h-10 rounded-xl flex items-center justify-center text-slate-500 hover:text-[#b83a4b] dark:text-slate-400 dark:hover:text-[#d66b7a] hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
              title="Sistem & Kullanıcı Yönetimi (RBAC)"
              aria-label="Yönetim Ayarları"
            >
              <Settings className="w-4.5 h-4.5" />
            </button>
          )}

          <button
            type="button"
            onClick={toggleCollapsed}
            className="p-2 rounded-xl text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
            title="Menüyü Genişlet"
          >
            <PanelLeftOpen className="w-4 h-4" />
          </button>
        </div>
      </aside>
    );
  }

  // Expanded Sidebar View (240px)
  return (
    <aside className="w-[240px] border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-[#0c121e] flex flex-col h-[calc(100vh-4rem)] select-none transition-all duration-300 z-20 shrink-0 justify-between">
      <div className="flex flex-col flex-1 overflow-hidden">
        {/* 1. Header: Section Title & Collapse Action */}
        <div className="p-2.5 px-3.5 border-b border-slate-200 dark:border-slate-800 bg-slate-50/70 dark:bg-[#141821]/90 flex items-center justify-between shrink-0">
          <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
            Navigasyon Menüsü
          </span>
          <button
            type="button"
            onClick={toggleCollapsed}
            className="p-1 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors cursor-pointer"
            title="Sol Menüyü Daralt"
          >
            <PanelLeftClose className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* 2. Primary Nav List */}
        <div className="p-2.5 space-y-1 border-b border-slate-200 dark:border-slate-800 shrink-0">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => onTabChange(item.id)}
                className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-semibold transition-all duration-150 cursor-pointer ${
                  isActive
                    ? 'bg-gradient-to-r from-[#b83a4b] to-[#821c2b] text-white shadow-sm shadow-[#821c2b]/25 font-bold'
                    : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800/60 hover:text-slate-900 dark:hover:text-white'
                }`}
              >
                <div className="flex items-center space-x-2.5">
                  <Icon className={`w-4 h-4 shrink-0 ${isActive ? 'text-white' : 'text-slate-400 group-hover:text-slate-600 dark:group-hover:text-slate-200'}`} />
                  <span className="truncate">{item.label}</span>
                </div>
                {item.badge !== undefined && (
                  <span
                    className={`text-[9px] font-mono px-1.5 py-0.5 rounded-full font-bold ${
                      isActive
                        ? 'bg-white/20 text-white'
                        : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700'
                    }`}
                  >
                    {item.badge}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* 3. Project Summary Card */}
        <div className="flex-1 p-3 overflow-y-auto space-y-3">
          <div className="p-3 rounded-xl bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 text-xs space-y-2.5">
            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400 block">
              Proje Özeti
            </span>
            <div className="space-y-1.5">
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5 border-b border-slate-200/50 dark:border-slate-800/60">
                <span>Test Planları:</span>
                <span className="font-mono font-bold text-slate-900 dark:text-slate-100">{testPlansCount}</span>
              </div>
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5 border-b border-slate-200/50 dark:border-slate-800/60">
                <span>Test Senaryoları:</span>
                <span className="font-mono font-bold text-slate-900 dark:text-slate-100">{testCasesCount}</span>
              </div>
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5">
                <span>Test Koşumları:</span>
                <span className="font-mono font-bold text-slate-900 dark:text-slate-100">{testRunsCount}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 4. Footer: Admin Settings Button (Sol Alt Köşe) + Collapse Action */}
      <div className="p-2.5 px-3 border-t border-slate-100 dark:border-slate-800/80 shrink-0 flex items-center justify-between gap-1 bg-slate-50/50 dark:bg-[#141821]/80">
        {/* Admin Settings Button (Bottom Left) */}
        {isAdmin && onOpenUserManagement ? (
          <button
            type="button"
            onClick={onOpenUserManagement}
            className="flex items-center space-x-1.5 px-2 py-1.5 rounded-lg text-xs font-semibold text-slate-700 dark:text-slate-300 hover:text-[#b83a4b] dark:hover:text-[#d66b7a] hover:bg-slate-200/70 dark:hover:bg-slate-800 transition-colors cursor-pointer"
            title="Sistem & Kullanıcı Yönetimi (RBAC Ayarları)"
            aria-label="Yönetim Ayarları"
          >
            <Settings className="w-3.5 h-3.5 text-[#b83a4b]" />
            <span className="text-[11px]">Ayarlar</span>
          </button>
        ) : (
          <div />
        )}

        {/* Collapse Toggle */}
        <button
          type="button"
          onClick={toggleCollapsed}
          className="flex items-center space-x-1 px-2 py-1.5 rounded-lg text-xs text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 hover:bg-slate-200/70 dark:hover:bg-slate-800 transition-colors cursor-pointer"
          title="Sol Menüyü Daralt"
        >
          <PanelLeftClose className="w-3.5 h-3.5" />
          <span className="text-[11px] hidden sm:inline">Daralt</span>
        </button>
      </div>
    </aside>
  );
};

export const ExplorerTree: React.FC<ExplorerTreeProps> = ({
  tree,
  rootTestCases = [],
  selectedProject,
  selectedCaseId,
  selectedSuiteId,
  onSelectCase,
  onSelectSuite,
  onAddSubSuite,
  onEditSuite,
  onDeleteSuite,
  onAddCaseInSuite,
  onOpenNewSuite,
  onOpenNewCase,
  onEditProject,
  onRunCase,
  onRunSuite,
  onReorderSuite,
}) => {
  const [expandedMap, setExpandedMap] = useState<Record<string, boolean>>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ALL');
  const [draggedSuiteId, setDraggedSuiteId] = useState<string | null>(null);
  const [dragOverSuiteId, setDragOverSuiteId] = useState<string | null>(null);
  const [isRootDragOver, setIsRootDragOver] = useState(false);

  const isSubTreeContainsId = (rootNode: SuiteTreeNode, targetId: string): boolean => {
    if (rootNode.id === targetId) return true;
    if (rootNode.children) {
      for (const child of rootNode.children) {
        if (isSubTreeContainsId(child, targetId)) return true;
      }
    }
    return false;
  };

  const findNodeInTree = (nodes: SuiteTreeNode[], id: string): SuiteTreeNode | null => {
    for (const n of nodes) {
      if (n.id === id) return n;
      if (n.children) {
        const found = findNodeInTree(n.children, id);
        if (found) return found;
      }
    }
    return null;
  };

  const isInvalidDropTarget = (draggedId: string | null, targetId: string): boolean => {
    if (!draggedId) return false;
    if (draggedId === targetId) return true;
    const draggedNode = findNodeInTree(tree, draggedId);
    if (draggedNode) {
      return isSubTreeContainsId(draggedNode, targetId);
    }
    return false;
  };

  const toggleExpand = (suiteId: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setExpandedMap((prev) => ({ ...prev, [suiteId]: !prev[suiteId] }));
  };

  const handleExpandAll = () => {
    const map: Record<string, boolean> = {};
    const traverse = (nodes: SuiteTreeNode[]) => {
      nodes.forEach((n) => {
        map[n.id] = true;
        if (n.children) traverse(n.children);
      });
    };
    traverse(tree);
    setExpandedMap(map);
  };

  const handleCollapseAll = () => {
    const map: Record<string, boolean> = {};
    const traverse = (nodes: SuiteTreeNode[]) => {
      nodes.forEach((n) => {
        map[n.id] = false;
        if (n.children) traverse(n.children);
      });
    };
    traverse(tree);
    setExpandedMap(map);
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'BLOCKER':
        return 'bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border-red-500/30';
      case 'CRITICAL':
        return 'bg-amber-500/10 dark:bg-amber-500/20 text-amber-600 dark:text-amber-400 border-amber-500/30';
      case 'NORMAL':
        return 'bg-blue-500/10 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 border-blue-500/30';
      case 'LOW':
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
      default:
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
    }
  };

  const getTypeBadge = (type: string) => {
    switch (type) {
      case 'WEB':
        return 'text-emerald-500 dark:text-emerald-400';
      case 'MOBILE':
        return 'text-purple-500 dark:text-purple-400';
      case 'API':
        return 'text-cyan-500 dark:text-cyan-400';
      default:
        return 'text-slate-400';
    }
  };

  const getLatestStatusBadge = (testCase: TestCase) => {
    const latestResult = testCase.results && testCase.results.length > 0 ? testCase.results[0] : null;
    const status = latestResult?.status;

    switch (status) {
      case 'PASSED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 font-mono font-bold"
            title={`Sonuç: PASSED (${latestResult?.executedAt ? new Date(latestResult.executedAt).toLocaleTimeString() : ''})`}
          >
            <CheckCircle2 className="w-2.5 h-2.5" />
            <span>PASS</span>
          </span>
        );
      case 'FAILED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/30 font-mono font-bold"
            title={`Sonuç: FAILED ${latestResult?.errorMessage ? `- ${latestResult.errorMessage}` : ''}`}
          >
            <XCircle className="w-2.5 h-2.5" />
            <span>FAIL</span>
          </span>
        );
      case 'SKIPPED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border border-slate-500/30 font-mono font-bold"
            title="Sonuç: SKIPPED"
          >
            <SkipForward className="w-2.5 h-2.5" />
            <span>SKIP</span>
          </span>
        );
      case 'BLOCKED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-amber-500/10 dark:bg-amber-500/20 text-amber-700 dark:text-amber-400 border border-amber-500/30 font-mono font-bold"
            title="Sonuç: BLOCKED"
          >
            <Slash className="w-2.5 h-2.5" />
            <span>BLOCK</span>
          </span>
        );
      default:
        return (
          <span
            className="text-[9px] px-1.5 py-0.5 rounded bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-300 dark:border-slate-700/50 font-mono"
            title="Henüz koşturulmadı"
          >
            -
          </span>
        );
    }
  };

  const handleDragStart = (e: React.DragEvent, suiteId: string) => {
    e.stopPropagation();
    setDraggedSuiteId(suiteId);
    e.dataTransfer.setData('text/plain', suiteId);
  };

  const handleDragEnd = () => {
    setDraggedSuiteId(null);
    setDragOverSuiteId(null);
    setIsRootDragOver(false);
  };

  const handleDragOverSuite = (e: React.DragEvent, targetSuiteId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (draggedSuiteId && !isInvalidDropTarget(draggedSuiteId, targetSuiteId)) {
      setDragOverSuiteId(targetSuiteId);
      setIsRootDragOver(false);
    }
  };

  const handleDropSuite = (e: React.DragEvent, targetSuiteId: string) => {
    e.preventDefault();
    e.stopPropagation();
    setDragOverSuiteId(null);
    if (draggedSuiteId && !isInvalidDropTarget(draggedSuiteId, targetSuiteId) && onReorderSuite) {
      onReorderSuite(draggedSuiteId, targetSuiteId, 0);
      setDraggedSuiteId(null);
    }
  };

  const handleDragOverRoot = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (draggedSuiteId) {
      setIsRootDragOver(true);
      setDragOverSuiteId(null);
    }
  };

  const handleDropRoot = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsRootDragOver(false);
    if (draggedSuiteId && onReorderSuite) {
      onReorderSuite(draggedSuiteId, null, 0);
      setDraggedSuiteId(null);
    }
  };

  const matchCaseStatus = (tc: TestCase) => {
    if (statusFilter === 'ALL') return true;
    const status = tc.results && tc.results.length > 0 ? tc.results[0].status : 'UNTESTED';
    if (statusFilter === 'UNTESTED') return !tc.results || tc.results.length === 0;
    return status === statusFilter;
  };

  const renderSuiteNode = (node: SuiteTreeNode, depth: number = 0) => {
    const isExpanded = expandedMap[node.id] ?? true;
    const isBeingDragged = draggedSuiteId === node.id;
    const isDragOver = dragOverSuiteId === node.id;
    const isSuiteSelected = selectedSuiteId === node.id;

    // Filter testcases if search query or status filter exists
    const filteredCases = node.testCases.filter((c) => {
      const matchesSearch = searchQuery
        ? c.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          c.code.toLowerCase().includes(searchQuery.toLowerCase())
        : true;
      const matchesStatus = matchCaseStatus(c);
      return matchesSearch && matchesStatus;
    });

    return (
      <div key={node.id} className="select-none">
        {/* Suite Header Item */}
        <div
          draggable
          onDragStart={(e) => handleDragStart(e, node.id)}
          onDragEnd={handleDragEnd}
          onDragOver={(e) => handleDragOverSuite(e, node.id)}
          onDrop={(e) => handleDropSuite(e, node.id)}
          onDragLeave={() => setDragOverSuiteId(null)}
          style={{ paddingLeft: `${depth * 14 + 12}px` }}
          className={`group flex items-center justify-between py-1.5 pr-2 rounded-lg transition-all cursor-pointer text-xs font-medium ${
            isBeingDragged
              ? 'opacity-40 border border-dashed border-amber-500 bg-amber-500/5'
              : isDragOver
              ? 'bg-blue-600/20 border-2 border-blue-500 text-blue-900 dark:text-blue-200 font-bold shadow-md ring-2 ring-blue-500/30'
              : isSuiteSelected
              ? 'bg-amber-500/15 dark:bg-amber-500/20 text-amber-900 dark:text-amber-200 font-bold border-l-2 border-amber-500 shadow-sm'
              : 'hover:bg-slate-200/60 dark:hover:bg-slate-800/70 text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white'
          }`}
          onClick={(e) => {
            toggleExpand(node.id, e);
            if (onSelectSuite) onSelectSuite(node);
          }}
        >
          <div className="flex items-center space-x-1.5 min-w-0">
            <span className="opacity-0 group-hover:opacity-40 cursor-grab hover:opacity-100 transition-opacity">
              <GripVertical className="w-3 h-3" />
            </span>

            <button
              onClick={(e) => toggleExpand(node.id, e)}
              className="p-0.5 text-slate-400 hover:text-slate-700 dark:hover:text-white rounded"
            >
              {isExpanded ? (
                <ChevronDown className="w-3.5 h-3.5" />
              ) : (
                <ChevronRight className="w-3.5 h-3.5" />
              )}
            </button>

            {isExpanded ? (
              <FolderOpen className="w-4 h-4 text-amber-500 dark:text-amber-400 shrink-0" />
            ) : (
              <Folder className="w-4 h-4 text-amber-500/80 dark:text-amber-400/80 shrink-0" />
            )}

            <span className="truncate font-semibold text-slate-800 dark:text-slate-200">{node.name}</span>
            <span className="text-[10px] text-slate-400 dark:text-slate-500 font-mono ml-1">
              ({node.testCases.length})
            </span>
            {isDragOver && (
              <span className="text-[10px] text-blue-600 dark:text-blue-400 font-bold ml-2 animate-pulse bg-blue-500/10 px-1.5 py-0.5 rounded border border-blue-500/30">
                ↳ Alt Suite yap
              </span>
            )}
          </div>

          {/* Quick Actions for Suite */}
          <div className="opacity-0 group-hover:opacity-100 flex items-center space-x-1 transition-opacity">
            <button
              onClick={(e) => {
                e.stopPropagation();
                onAddCaseInSuite(node.id);
              }}
              title="Test Case Ekle"
              className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400"
            >
              <Plus className="w-3 h-3" />
            </button>

            {onEditSuite && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onEditSuite(node);
                }}
                title="Suite Düzenle"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-amber-500"
              >
                <Pencil className="w-3 h-3" />
              </button>
            )}

            {onDeleteSuite && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  if (confirm(`"${node.name}" isimli suite klasörünü silmek istediğinize emin misiniz?`)) {
                    onDeleteSuite(node.id);
                  }
                }}
                title="Suite Sil"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-red-500"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Children & Test Cases */}
        {isExpanded && (
          <div className="space-y-0.5">
            {/* Child Suites */}
            {node.children.map((childNode) => renderSuiteNode(childNode, depth + 1))}

            {/* Test Cases inside this suite */}
            {filteredCases.map((tc) => {
              const isSelected = selectedCaseId === tc.id;
              return (
                <div
                  key={tc.id}
                  style={{ paddingLeft: `${(depth + 1) * 14 + 18}px` }}
                  onClick={() => onSelectCase(tc)}
                  className={`group flex items-center justify-between py-1.5 pr-2 rounded-lg transition-all cursor-pointer text-xs ${
                    isSelected
                      ? 'bg-blue-500/10 dark:bg-blue-600/20 text-blue-700 dark:text-blue-300 font-semibold border-l-2 border-blue-500 shadow-sm'
                      : 'hover:bg-slate-200/50 dark:hover:bg-slate-800/50 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'
                  }`}
                >
                  <div className="flex items-center space-x-2 min-w-0 flex-1 mr-2">
                    <FileText className={`w-3.5 h-3.5 shrink-0 ${getTypeBadge(tc.type)}`} />
                    <span className="font-mono text-[10px] text-slate-400 dark:text-slate-500 shrink-0 font-bold">
                      {tc.code}
                    </span>
                    <span className="truncate">{tc.title}</span>
                  </div>

                  <div className="flex items-center space-x-1.5 shrink-0">
                    {/* Latest Status Badge */}
                    {getLatestStatusBadge(tc)}

                    {/* Run Command Button */}
                    {onRunCase && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onRunCase(tc);
                        }}
                        title="Test Case'i Koştur (Run)"
                        className="p-1 rounded bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 flex items-center space-x-1 transition-all opacity-0 group-hover:opacity-100 font-semibold text-[10px]"
                      >
                        <Play className="w-3 h-3 fill-current text-emerald-500" />
                        <span>Run</span>
                      </button>
                    )}

                    <span
                      className={`text-[9px] px-1.5 py-0.5 rounded border font-mono font-bold ${getPriorityColor(
                        tc.priority
                      )}`}
                    >
                      {tc.priority}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    );
  };

  return (
    <aside className="w-80 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/50 flex flex-col h-[calc(100vh-4rem)] select-none transition-colors duration-200">
      {/* Active Test Plan Info & Actions */}
      {selectedProject && (
        <div className="p-3.5 bg-slate-50/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 space-y-2.5">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 min-w-0">
              <span className="font-mono text-[10px] font-bold px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 shrink-0">
                [{selectedProject.key}]
              </span>
              <h2 className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate" title={selectedProject.name}>
                {selectedProject.name}
              </h2>
            </div>
            <div className="flex items-center space-x-1.5 shrink-0">
              <span className="text-[10px] text-slate-400 font-mono">Test Planı</span>
              {onEditProject && (
                <button
                  onClick={() => onEditProject(selectedProject)}
                  className="p-1 rounded-md text-slate-400 hover:text-rose-500 hover:bg-rose-500/10 transition-colors"
                  title="Test Planını Düzenle / Sil"
                >
                  <Pencil className="w-3 h-3" />
                </button>
              )}
            </div>
          </div>

          {/* Plan-level Buttons: Yeni Suite & Yeni Case */}
          <div className="grid grid-cols-2 gap-2 pt-1">
            <button
              onClick={() => onOpenNewSuite ? onOpenNewSuite() : onAddSubSuite('')}
              className="flex items-center justify-center space-x-1.5 px-2.5 py-1.5 text-xs font-semibold bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 rounded-lg transition-all shadow-sm active:scale-95 cursor-pointer"
