                                  className={`px-2 py-1 rounded-[6px] text-[11px] font-mono font-bold ${
                                    currentStatus === 'PASSED'
                                      ? 'bg-emerald-600 text-white'
                                      : 'bg-emerald-500/10 text-emerald-600'
                                  }`}
                                >
                                  PASS
