                                <button
                                  type="button"
                                  onClick={() => handleInstantStatusChange(testCase.id, 'BLOCKED')}
                                  className={`px-2 py-1 rounded-[6px] text-[11px] font-mono font-bold ${
                                    currentStatus === 'BLOCKED'
